'use strict'

function listOrders(db, customerId) {
  return db.orders
    .filter(o => o.customerId === customerId)
    .sort((a, b) => b.createdAt - a.createdAt)
}

// pct is a fraction: 0.2 = 20 %
function applyDiscount(order, pct) {
  const capped = Math.min(pct, 0.9)
  return { ...order, totalCents: Math.round(order.totalCents * (1 - capped)) }
}

module.exports = { listOrders, applyDiscount }
